// The first call returns the hero and lists every other section on the page.
const first = $input.first().json
const settings = $('Set Website URL').first().json
const rest = (first.sections || [])
  .filter(s => s.selector !== first.selector)
  .sort((a, b) => a.order - b.order)
  .slice(0, 15)
// A page with only a hero still finishes: the next node then repeats the
// hero call, which is cached (free) and dropped as a duplicate later.
if (!rest.length) return [{ json: { url: settings.website }, pairedItem: { item: 0 } }]
return rest.map(s => ({ json: { url: settings.website, selector: s.selector, section: s.label, order: s.order }, pairedItem: { item: 0 } }))

// Hero plus every section, sorted by where they sit on the page, duplicates dropped.
const hero = $('Extract Hero and Find Sections').first().json
const order = Object.fromEntries((hero.sections || []).map(s => [s.selector, s.order]))
const labelOf = Object.fromEntries((hero.sections || []).map(s => [s.selector, String(s.label || '').split(/\s+/).slice(0, 4).join(' ')]))
const results = $input.all().map(i => i.json)
const failed = results.filter(r => !r.code).length
const seen = new Set()
const all = [hero, ...results].filter(r => r.code && !seen.has(r.selector) && seen.add(r.selector))
  .sort((a, b) => (order[a.selector] ?? (a === hero ? 0 : 999)) - (order[b.selector] ?? (b === hero ? 0 : 999)))
// Every section is its own Elementor template; their content goes into one page, in order.
const content = []
for (const r of all) {
  try { content.push(...JSON.parse(r.code).content) } catch (e) {}
}
if (!content.length) throw new Error('No section could be rebuilt as Elementor. Check the URL in Set Website URL.')
const host = String($('Set Website URL').first().json.website).split('/')[2].replace(/^www\./, '')
const template = { content, page_settings: [], version: '0.4', title: 'MiroMiro - ' + host + ' page', type: 'page' }
return [{ json: { sections: all.length, failed, template: JSON.stringify(template) }, pairedItem: { item: 0 } }]
